import React, { useEffect, useState } from "react";

interface Question {
  id: number;
  domain: string;
  question_text: string;
  maturity_level: number;
}

const App: React.FC = () => {
  const [questions, setQuestions] = useState<Question[]>([]);

  useEffect(() => {
    fetch("http://localhost:3001/questions")
      .then((res) => res.json())
      .then((data) => setQuestions(data))
      .catch((err) => console.error("Error fetching questions:", err));
  }, []);

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <h1 className="text-3xl font-bold text-blue-600 mb-6">Cybersecurity Questions</h1>
      <ul className="space-y-4">
        {questions.map((q) => (
          <li key={q.id} className="bg-white rounded shadow p-4">
            <p className="text-gray-800">
              <strong className="text-purple-700">{q.domain}</strong>: {q.question_text}{" "}
              <span className="text-sm text-gray-500">(Level {q.maturity_level})</span>
            </p>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default App;
